// Explicit conversation state machine. The stage is authoritative and the message is
// interpreted in light of it, rather than the stage being guessed from keywords alone.
// Stages: IDLE -> AWAITING_TOPIC -> AWAITING_DIRECTION -> ARTICLE_READY
const raw = $input.item.json.message?.text || '';
const text = raw.toLowerCase().trim();
const chatId = $input.item.json.message.chat.id;
const sd = $getWorkflowStaticData('global');
const key = 'session_' + chatId;
const s = sd[key] || { stage: 'IDLE' };
if (!s.stage) s.stage = 'IDLE';

const CATS = {
  business:      { label:'Business',      slug:'business-finance',   wpId:2,    query:'business OR finance news' },
  finance:       { label:'Business',      slug:'business-finance',   wpId:2,    query:'business OR finance news' },
  entertainment: { label:'Entertainment', slug:'entertainment-arts', wpId:105,  query:'entertainment OR arts OR culture news' },
  arts:          { label:'Entertainment', slug:'entertainment-arts', wpId:105,  query:'entertainment OR arts OR culture news' },
  environment:   { label:'Environment',   slug:'environment-nature', wpId:162,  query:'environment OR nature OR climate news' },
  nature:        { label:'Environment',   slug:'environment-nature', wpId:162,  query:'environment OR nature OR climate news' },
  science:       { label:'Science',       slug:'science-technology', wpId:296,  query:'science OR technology OR AI news' },
  technology:    { label:'Science',       slug:'science-technology', wpId:296,  query:'science OR technology OR AI news' },
  politics:      { label:'Politics',      slug:'politics-global',    wpId:5325, query:'UK politics OR global news OR parliament OR international affairs' },
  global:        { label:'Politics',      slug:'politics-global',    wpId:5325, query:'UK politics OR global news OR parliament OR international affairs' }
};

const isReset     = text === '/start' || text === '/reset' ||
  /\b(new article|new post|start over|start again|fresh start|another article|write another)\b/.test(text);
const isStatusReq = text === '/status';

// Anchored at the start of the message so it cannot collide with ordinary prose. It must be
// tested before wantsWp, because that regex matches \bpost\b and \bwp\b - so a request like
// "image london skyline on the post" would otherwise route to WordPress.
const imageMatch = raw.trim().match(/^\/?image\b[:\s]*(.*)$/i);
const wantsImage  = !!imageMatch;
const imageQuery  = imageMatch ? imageMatch[1].trim() : '';

const wantsWp     = /\b(post|publish|wordpress|wp|send to wp|go live)\b/.test(text);
const wantsSocial = /\b(social|twitter|linkedin|facebook|instagram|hashtag|thumbnail)\b/.test(text);

let intent = 'unknown';
let statusMsg = '';
let newsQuery = '';
let isPublish = false;

if (isStatusReq) {
  intent = 'status';
} else if (isReset) {
  intent = 'reset';
  statusMsg = '\ud83d\udd04 Resetting your PromoMag session...';
} else if (wantsImage) {
  // Deliberately stage-independent: the target is whatever was published most recently,
  // which may be a scheduled post from a session that no longer exists.
  intent = imageQuery ? 'image' : 'unknown';
  statusMsg = '\ud83d\uddbc\ufe0f Searching for *' + imageQuery + '* and checking the latest post...';
} else if (wantsWp && s.stage === 'ARTICLE_READY') {
  intent = 'wordpress';
  isPublish = /\b(publish|go live|make it live|post live)\b/.test(text);
  statusMsg = isPublish
    ? '\ud83d\ude80 *Publishing to PromoMag...*'
    : '\ud83d\udce4 *Saving to PromoMag as a draft...*';
} else if (wantsSocial && s.stage === 'ARTICLE_READY') {
  intent = 'social';
  statusMsg = '\ud83d\udcf1 *Building your social pack...*';
} else if (wantsWp || wantsSocial) {
  // Asked to post or socialise before an article exists - explain rather than misread it.
  intent = 'unknown';
} else if (s.stage === 'IDLE') {
  const m = text.match(/business|finance|entertainment|arts|environment|nature|science|technology|politics|global/);
  if (m) {
    const c = CATS[m[0]];
    s.category = c;
    intent = 'category';
    newsQuery = c.query;
    statusMsg = '\ud83d\udd0d Researching trending *' + c.label + '* stories from Reuters, Bloomberg, BBC and more...\n\n_This takes 20\u201330 seconds._';
  }
} else if (s.stage === 'AWAITING_TOPIC') {
  intent = 'topic';
  statusMsg = '\ud83d\udccb Got it \u2014 building your outline...';
} else if (s.stage === 'AWAITING_DIRECTION') {
  intent = 'direction';
  statusMsg = '\u270d\ufe0f *Writing the full article now...*\n\n_30\u201360 seconds._';
}

const IMAGE_HELP = 'Send *image <search term>* at any time to replace the featured image on the most recent post.';

const STAGE_HELP = {
  IDLE: 'Choose a category to begin:\n\nBusiness & Finance | Entertainment & Arts | Environment & Nature | Science & Technology | Politics & Global News\n\n' + IMAGE_HELP,
  AWAITING_TOPIC: 'Reply with a topic number (1\u20135) from the list above.',
  AWAITING_DIRECTION: 'Reply with the stance for the article:\n\n1. Supportive \u2014 argue in favour\n2. Critical \u2014 argue against\n3. Neutral \u2014 report it straight',
  ARTICLE_READY: 'Reply *post to WordPress* for a draft, *publish to WordPress* to go live, or *social* for a social pack.\n\n' + IMAGE_HELP
};

const guidanceMsg = '\ud83e\udd14 I did not follow that.\n\n' + (STAGE_HELP[s.stage] || STAGE_HELP.IDLE) +
  '\n\nSend /status to see where we are, or /reset to start again.';

const statusReport = '\ud83d\udccd *Session status*\n\nStage: `' + s.stage + '`\nCategory: ' +
  (s.category ? s.category.label : '\u2014') + '\nTopic: ' + (s.topicTitle || '\u2014') +
  '\nStance: ' + (s.direction || '\u2014') +
  '\nArticle drafted: ' + (s.stage === 'ARTICLE_READY' ? 'yes' : 'no') + '\n\n' + STAGE_HELP[s.stage];

sd[key] = s;

// Legacy field names retained so the existing branch conditions keep working unchanged.
// `query` duplicates imageQuery because the image sub-workflow reads j.query on a
// passthrough trigger, which does no field mapping of its own.
return [{ json: {
  chatId,
  originalText: raw,
  intent,
  stage: s.stage,
  isStatusReq: intent === 'status',
  isUnknown:   intent === 'unknown',
  isReset:     intent === 'reset',
  isWPIntent:  intent === 'wordpress',
  isCategory:  intent === 'category',
  isTopicPick: intent === 'topic',
  isDirection: intent === 'direction',
  isImage:     intent === 'image',
  imageQuery,
  query: imageQuery,
  newsQuery,
  isPublish,
  statusMsg,
  guidanceMsg,
  statusReport,
  category: s.category || null
}}];

const CHUNK_SIZE = 3800;
const TELEGRAM_MAX = 4000;
const output = $input.item.json.output || '';
const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const items = [];

// Bound each block at [/BLOCK] OR at the next [BLOCK: marker, whichever comes first.
// Writing agents sometimes omit the closers entirely; the old 'take everything to the end'
// fallback made METADATA swallow the whole article and breach Telegram's 4096-char limit.
const extractBlock = (tag, text) => {
  const open = '[BLOCK:' + tag + ']';
  const start = text.indexOf(open);
  if (start === -1) return null;
  const contentStart = start + open.length;
  const closeIdx = text.indexOf('[/BLOCK]', contentStart);
  const nextIdx = text.indexOf('[BLOCK:', contentStart);
  const bounds = [closeIdx, nextIdx].filter(i => i !== -1);
  const end = bounds.length ? Math.min.apply(null, bounds) : text.length;
  return text.slice(contentStart, end).trim();
};

const parseField = (block, field) => {
  if (!block) return '';
  const lines = block.split('\n');
  for (const line of lines) {
    const prefix = field + ':';
    if (line.trim().startsWith(prefix)) return line.trim().slice(prefix.length).trim();
  }
  return '';
};

const chunkText = (text) => {
  const chunks = [];
  let remaining = String(text || '');
  while (remaining.length > 0) {
    let chunk = remaining.slice(0, CHUNK_SIZE);
    if (remaining.length > CHUNK_SIZE) {
      const lastNewline = chunk.lastIndexOf('\n');
      if (lastNewline > CHUNK_SIZE * 0.5) chunk = chunk.slice(0, lastNewline);
    }
    chunks.push(chunk.trim());
    remaining = remaining.slice(chunk.length).trim();
  }
  return chunks;
};

// Last line of defence: nothing leaves this node above the Telegram limit, whatever
// shape the model returned. A 400 here aborts the whole run before the image path.
const pushMsg = (text, generateImage) => {
  const parts = chunkText(text);
  for (let i = 0; i < parts.length; i++) {
    const isLast = i === parts.length - 1;
    items.push({ json: {
      chatId: chatId,
      text: parts[i].slice(0, TELEGRAM_MAX),
      generateImage: generateImage && isLast
    }});
  }
};

const metadataBlock = extractBlock('METADATA', output);
const articleBlock = extractBlock('ARTICLE', output);
const seoBlock = extractBlock('SEO', output);
const isCompleteArticle = !!(metadataBlock && articleBlock && seoBlock);
const hasBlocks = !!(metadataBlock || articleBlock || seoBlock);

const detectCategory = (meta) => {
  const author = parseField(meta, 'Author').toLowerCase();
  if (author.indexOf('business') !== -1 || author.indexOf('finance') !== -1) return 'business-finance';
  if (author.indexOf('entertainment') !== -1 || author.indexOf('arts') !== -1) return 'entertainment-arts';
  if (author.indexOf('environment') !== -1 || author.indexOf('nature') !== -1) return 'environment-nature';
  if (author.indexOf('science') !== -1 || author.indexOf('technology') !== -1) return 'science-technology';
  if (author.indexOf('politics') !== -1 || author.indexOf('global') !== -1 || author.indexOf('news') !== -1) return 'politics-global';
  return 'uncategorized';
};

if (isCompleteArticle) {
  const staticData = $getWorkflowStaticData('global');
  staticData['currentChatId'] = chatId; // reliable chatId for post-Merge nodes

  // Prefer the category the user actually chose this session over guessing from the byline.
  const sess = staticData['session_' + chatId] || {};
  const chosen = sess.category && sess.category.slug ? sess.category.slug : detectCategory(metadataBlock);

  staticData['article_' + chatId] = {
    title: parseField(metadataBlock, 'Title'),
    slug: parseField(metadataBlock, 'Slug'),
    excerpt: parseField(metadataBlock, 'Meta'),
    tags: parseField(metadataBlock, 'Tags'),
    imageDescription: parseField(metadataBlock, 'Image'),
    content: articleBlock,
    category: chosen,
    wpMediaId: 0,
    wpMediaUrl: null
  };

  // Advance the state machine so the WordPress and social gates open.
  sess.stage = 'ARTICLE_READY';
  staticData['session_' + chatId] = sess;
}

if (isCompleteArticle) {
  pushMsg('\ud83d\udcf0 *Article Brief*\n\n' + metadataBlock, false);

  const clean = articleBlock
    .split('\n')
    .filter(function(l) { return !l.trim().match(/^#{1,6}\s/); })
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const chunks = chunkText(clean);
  for (let i = 0; i < chunks.length; i++) {
    const label = chunks.length > 1
      ? '\u270d\ufe0f *Article Body (' + (i + 1) + '/' + chunks.length + ')*\n\n' + chunks[i]
      : '\u270d\ufe0f *Article Body*\n\n' + chunks[i];
    items.push({ json: { chatId: chatId, text: label.slice(0, TELEGRAM_MAX), generateImage: false } });
  }

  pushMsg('\ud83d\udce3 *Next Step*\n\n' + seoBlock, true);

} else if (hasBlocks) {
  const partialText = output
    .replace(/\[BLOCK:[^\]]+\]/g, '')
    .replace(/\[\/BLOCK\]/g, '')
    .trim();
  pushMsg(partialText || output, false);
} else {
  pushMsg(output || 'No response generated.', false);
}

return items.length > 0
  ? items
  : [{ json: { chatId: chatId, text: '\u26a0\ufe0f No content returned. Please try again.', generateImage: false } }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const staticData = $getWorkflowStaticData('global');
const article = staticData['article_' + chatId];

// Read publish intent from Detect Stage
const isPublish = $('Detect Stage').item.json.isPublish || false;

if (!article) {
  return [{ json: {
    chatId: chatId, error: true,
    errorMsg: '⚠️ *No article found*\n\nDraft an article first, then reply *post to WordPress* or *publish to WordPress*.'
  }}];
}

return [{ json: {
  chatId: chatId, error: false,
  title: article.title || 'Untitled Article',
  content: article.content || '',
  slug: article.slug || '',
  excerpt: article.excerpt || '',
  tags: article.tags || '',
  category: article.category || 'uncategorized',
  wpMediaId: article.wpMediaId || 0,
  isPublish: isPublish
}}];

const raw = $json.content || '';

const html = raw
  .split('\n')
  .filter(function(line) { return !line.trim().match(/^#{1,6}\s/); })
  .join('\n')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '<em>$1</em>')
  .replace(/^>\s?(.+)/gm, '<blockquote>$1</blockquote>')
  .split(/\n\n+/)
  .map(function(para) {
    const t = para.trim();
    if (!t) return '';
    if (t.startsWith('<blockquote>')) return t;
    return '<p>' + t.replace(/\n/g, '<br>') + '</p>';
  })
  .filter(Boolean)
  .join('\n\n');

return [{ json: {
  chatId: $json.chatId,
  title: $json.title,
  content: html,
  slug: $json.slug,
  excerpt: $json.excerpt,
  tags: $json.tags,
  category: $json.category || 'uncategorized',
  wpMediaId: $json.wpMediaId || 0,
  isPublish: $json.isPublish || false
}}];

// PromoMag.co.uk verified category IDs
// Source: https://promomag.co.uk/wp-json/wp/v2/categories
const categoryMap = {
  'business-finance':   2,
  'entertainment-arts': 105,
  'environment-nature': 162,
  'science-technology': 296,
  'politics-global':    5325
};

const slug = $json.category || 'uncategorized';
const categoryId = categoryMap[slug] || 1;

return [{ json: {
  chatId: $json.chatId,
  title: $json.title,
  content: $json.content,
  slug: $json.slug,
  excerpt: $json.excerpt,
  tags: $json.tags,
  wpMediaId: $json.wpMediaId || 0,
  categoryId: categoryId,
  isPublish: $json.isPublish || false
}}];

