const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'] || $json.chatId;
const wpResponse = $input.item.json.body || $input.item.json;
const postId = wpResponse.id;
const isPublished = wpResponse.status === 'publish';
const postUrl = wpResponse.link || ('https://promomag.co.uk/?p=' + postId);

return [{ json: {
  chatId: chatId,
  text: isPublished
    ? '🚀 *Article published on PromoMag!*\n\n📄 Status: Live\n\n🔗 [View Article](' + postUrl + ')\n🔗 [Edit in WP Admin](https://promomag.co.uk/wp-admin/post.php?post=' + postId + '&action=edit)'
    : '✅ *Article saved as draft on PromoMag!*\n\n📄 Status: Draft\n\n🔗 [Open in WP Admin](https://promomag.co.uk/wp-admin/post.php?post=' + postId + '&action=edit)\n\n_Review and publish when ready._'
}}];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'] || $json.chatId;
const err = $json.error ? ($json.error.message || JSON.stringify($json.error)) : JSON.stringify($json);

// Telegram parses this message as Markdown and a raw WP error payload is full of
// underscores, asterisks, brackets and backticks. An unbalanced one returns a 400
// and the failure notice itself fails to send.
const safe = String(err)
  .replace(/[_*\[\]`]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 200);

return [{ json: {
  chatId: chatId,
  text: '\u26a0\ufe0f *WordPress Post Failed*\n\nThe article is still stored. Reply *post to WordPress* to retry.\n\nError: ' + safe
}}];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const errorMsg = $input.item.json.error ? $input.item.json.error.message : 'Unknown error';
return [{ json: { chatId: chatId, text: '⚠️ *PromoMag Error*

Something went wrong. Send /reset to start fresh.

_' + String(errorMsg).slice(0, 200) + '_' } }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const sd = $getWorkflowStaticData('global');

// Clear the state machine session plus every per-chat scratch key.
delete sd['session_' + chatId];
delete sd['article_' + chatId];
delete sd['categoryChosen_' + chatId];
delete sd['researchBrief_' + chatId];
delete sd['researchInput_' + chatId];
delete sd['pendingPost_' + chatId];

// Bump the counter so the memory session key changes too.
const counterKey = 'sessionCounter_' + chatId;
sd[counterKey] = (sd[counterKey] || 0) + 1;

return [{ json: {
  chatId: chatId,
  text: '\u2705 *Session reset.*\n\nAll previous article data cleared. Choose a category to begin:\n\nBusiness & Finance | Entertainment & Arts | Environment & Nature | Science & Technology | Politics & Global News'
}}];

const staticData = $getWorkflowStaticData('global');

let chatId;
try {
  chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
} catch(e) {
  chatId = staticData['currentChatId'];
}

if (!chatId) throw new Error('Could not resolve chatId for image generation');

const article = staticData['article_' + chatId];
if (!article) throw new Error('No stored article found for chatId: ' + chatId);

const imageDescription = article.imageDescription || article.title || 'Professional editorial magazine photograph';

const imagePrompt = [
  'Professional editorial magazine header photograph for a web publication.',
  imageDescription,
  'Cinematic lighting, photojournalism aesthetic, widescreen 16:9 composition.',
  'No people, no faces, no portraits, no humans visible.',
  'Focus on objects, landscapes, technology, architecture, abstract concepts, or symbolic imagery.',
  'No text, no watermarks, no logos.'
].join(' ');

return [{ json: { chatId, imagePrompt } }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const staticData = $getWorkflowStaticData('global');
const article = staticData['article_' + chatId];
const title = (article && article.title) ? article.title : 'promomag-article';
const filename = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60) + '-featured.png';

// Pass binary data through so Upload to WP Media can find imageData
return [{
  json: { chatId: chatId, filename: filename },
  binary: $input.item.binary
}];

const staticData = $getWorkflowStaticData('global');
const chatId = staticData['currentChatId'];

if (!chatId) {
  return [{ json: { chatId: null, wpMediaId: null, wpMediaUrl: null } }];
}

const raw = $input.item.json;
const body = raw.body || raw;

const wpMediaId = body.id || null;
const wpMediaUrl = body.source_url
  || (body.guid && body.guid.rendered)
  || (body.guid && body.guid.raw)
  || null;

if (wpMediaId) {
  if (staticData['article_' + chatId]) {
    staticData['article_' + chatId].wpMediaId = wpMediaId;
    staticData['article_' + chatId].wpMediaUrl = wpMediaUrl;
  }
}

// Log for debugging
if (!wpMediaUrl) {
  console.log('Store WP Media ID: wpMediaUrl is null. Raw response:', JSON.stringify(raw).slice(0, 500));
}

return [{ json: {
  chatId,
  wpMediaId,
  wpMediaUrl,
  hasUrl: !!wpMediaUrl
} }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const raw = $input.item.json;

// Extract error in whatever format n8n provides
let err = 'Unknown error';
if (raw.error) {
  if (typeof raw.error === 'string') {
    err = raw.error;
  } else if (raw.error.message) {
    err = raw.error.message;
  } else if (raw.error.description) {
    err = raw.error.description;
  } else {
    err = JSON.stringify(raw.error).slice(0, 300);
  }
} else if (raw.message) {
  err = raw.message;
} else if (raw.statusCode) {
  err = 'HTTP ' + raw.statusCode + ': ' + JSON.stringify(raw).slice(0, 200);
}

// Sourcing and generation are separate from the WP upload and the Telegram preview,
// so do not blame "generation" for what is usually an upload or send failure.
return [{ json: {
  chatId: chatId,
  text: '\u26a0\ufe0f *Featured image not attached*\n\nThe article itself is saved. You can still post it \u2014 reply *post to WordPress* \u2014 then add a featured image manually in WP Admin.\n\n_Error: ' + String(err).slice(0, 300) + '_'
}}];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const staticData = $getWorkflowStaticData('global');
const category = (()=>{try{return $('Detect Stage').item.json.newsQuery}catch(e){return $getWorkflowStaticData('global')['currentNewsQuery']||''}})() || '';

const now = new Date();
const currentDate = now.toLocaleDateString('en-GB', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

// Collect all RSS data from input items (could be multiple feeds merged)
let allRssData = '';
const inputItems = $input.all ? $input.all() : [$input.item];
for (const item of inputItems) {
  allRssData += (item.json.data || item.json.content || '') + '\n';
}

// Google News delivers <description> as CDATA-escaped HTML: &lt;a href="..."&gt;Headline&lt;/a&gt;.
// The old /<[^>]+>/g strip matched nothing because the angle brackets arrive as entities, so every
// description survived as ~300 chars of base64 Google redirect URL. Fifteen of those, resent on all
// five agent turns, were the bulk of the 13,566 input tokens that tripped OpenAI's rate limit.
const decodeEntities = (s) => String(s || '')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&apos;/g, "'")
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&');

const stripTags = (s) => decodeEntities(s)
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

const collected = [];
const seen = new Set();
const itemRegex = /<item>[\s\S]*?<\/item>/g;
let match;
while ((match = itemRegex.exec(allRssData)) !== null && collected.length < 60) {
  const rssItem = match[0];

  const titleMatch = rssItem.match(/<title><!\[CDATA\[([\s\S]*?)\]\]><\/title>/) || rssItem.match(/<title>([\s\S]*?)<\/title>/);
  const rawTitle = titleMatch ? stripTags(titleMatch[1]) : '';
  if (!rawTitle || rawTitle.toLowerCase().includes('google news')) continue;
  if (seen.has(rawTitle)) continue;
  seen.add(rawTitle);

  const lastDash = rawTitle.lastIndexOf(' - ');
  const headline = lastDash > 0 ? rawTitle.slice(0, lastDash).trim() : rawTitle;
  const titleSource = lastDash > 0 ? rawTitle.slice(lastDash + 3).trim() : '';

  // Prefer the feed's own <source> element over the suffix parsed off the headline.
  const srcMatch = rssItem.match(/<source[^>]*>([\s\S]*?)<\/source>/);
  const source = (srcMatch ? stripTags(srcMatch[1]) : '') || titleSource;

  const pubDateMatch = rssItem.match(/<pubDate>([\s\S]*?)<\/pubDate>/);
  const pubDate = pubDateMatch ? pubDateMatch[1].trim() : '';
  const parsed = pubDate ? Date.parse(pubDate) : NaN;
  const ts = isNaN(parsed) ? 0 : parsed;

  // Once decoded, the description is the headline again wrapped in a link, carrying no information
  // the headline does not. Strip URLs and keep it only when it genuinely adds words.
  const descMatch = rssItem.match(/<description><!\[CDATA\[([\s\S]*?)\]\]><\/description>/) || rssItem.match(/<description>([\s\S]*?)<\/description>/);
  let description = descMatch ? stripTags(descMatch[1]) : '';
  if (description) {
    description = description.replace(/https?:\/\/\S+/g, ' ').replace(/\s+/g, ' ').trim();
    const isEcho = norm(description).indexOf(norm(headline)) !== -1
      && description.length < headline.length + 40;
    if (isEcho || description.length < 40) description = '';
  }

  collected.push({ headline, source, pubDate, ts, description });
}

// Google News mixes evergreen and archive pages into a current-affairs query; a 2024 explainer
// presented as today's news is what produced topic briefs with no live hook. Prefer recent items,
// but never starve the agent: if too few survive the window, fall back to the full set.
const MAX_AGE_DAYS = 45;
const cutoff = now.getTime() - MAX_AGE_DAYS * 86400000;
