// Only a Research Agent brief carries TOPIC markers. Raw RSS headlines do not, and the old
// researchInput_ fallback formatted them into a single malformed 'topic' that read as success.
const hasTopics = /\bTOPIC\s+\d+\b/i.test(brief);
const parts = hasTopics
  ? brief.split(/\bTOPIC\s+\d+\b/i).map(p => p.trim()).filter(Boolean)
  : [];

const topics = parts.map(p => {
  const m = p.match(/Title:\s*(.+)/i);
  return { title: m ? m[1].trim() : p.split('\n')[0].slice(0, 120), body: p };
}).slice(0, 5);

// Never hard-fail here: a thrown error kills the run silently and leaves the user staring
// at the last status message with no idea anything went wrong.
if (!topics.length) {
  const s0 = sd['session_' + chatId] || {};
  s0.stage = 'IDLE';
  delete s0.topics;
  delete s0.topicTitle;
  sd['session_' + chatId] = s0;

  // Parse Research Output already records why the agent returned no TOPIC blocks. Without
  // surfacing it, every cause renders as "no stories could be pulled" - which sent two
  // debugging sessions chasing the research when the real fault was an OpenAI rate limit.
  let err = '';
  try { err = String($('Parse Research Output').first().json.researchError || ''); } catch(e) {}

  let text;
  if (/rate limit/i.test(err)) {
    text = '\u23f3 *OpenAI rate limit reached.*\n\nThe research ran, but OpenAI refused the final call. Wait a full minute before sending the category again \u2014 retrying immediately consumes the allowance the retry itself needs.';
  } else if (err) {
    const safe = err.replace(/[_*\[\]`]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 200);
    text = '\u26a0\ufe0f *Research failed.*\n\nNo topics were produced. Send the category again in a moment, or pick a different one.\n\n_' + safe + '_';
  } else {
    text = '\u26a0\ufe0f *Research came back empty.*\n\nNo stories could be pulled for that category just now. Send the category again in a moment, or pick a different one.';
  }

  return [{ json: { chatId, researchOk: false, researchError: err, text } }];
}

const s = sd['session_' + chatId] || { stage: 'IDLE' };
s.topics = topics.map(t => t.title);
s.stage = 'AWAITING_TOPIC';
sd['session_' + chatId] = s;

let text = '\ud83d\udcf0 *Five stories worth writing*\n\n';
topics.forEach((t, i) => {
  const sig = (t.body.match(/Significance:\s*(.+)/i) || [])[1] || '';
  const src = (t.body.match(/Sources:\s*(.+)/i) || [])[1] || '';
  const dt  = (t.body.match(/Date:\s*(.+)/i) || [])[1] || '';
  text += '*' + (i + 1) + '. ' + t.title + '*\n';
  if (sig) text += sig + '\n';
  if (src) text += '_' + src + (dt ? ', ' + dt : '') + '_\n';
  text += '\n';
});
text += 'Reply with a number (1\u20135) to pick one.';

return [{ json: { chatId, researchOk: true, text } }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const sd = $getWorkflowStaticData('global');
const s = sd['session_' + chatId] || {};
const raw = (()=>{try{return $('Detect Stage').item.json.originalText || ''}catch(e){return ''}})();
const topics = s.topics || [];
const brief = sd['researchBrief_' + chatId] || '';

// Same hard-fail contract as Auto-Select Top Topic. This was the last unguarded route from an
// empty or malformed brief to a published article: `parts[idx] || brief` silently handed the
// whole brief - or, when gpt-4o-mini returned JSON, two characters of it - to the writer, which
// then invented the article wholesale. Silence here is worse than a failed run.
if (!brief.trim()) {
  throw new Error('No research brief stored for chat ' + chatId + ' - a topic pick arrived with nothing to pick from. Send /reset and choose the category again.');
}
if (!/\bTOPIC\s+\d+\b/i.test(brief)) {
  throw new Error('Stored research brief carries no TOPIC markers - the Research Agent drifted from the required plain-text format. Brief starts: ' + brief.slice(0, 120));
}

// Resolve the pick: a number first, then a loose title match, then fall back to the first.
let idx = -1;
const num = raw.match(/[1-5]/);
if (num) idx = parseInt(num[0], 10) - 1;
if (idx < 0 || idx >= topics.length) {
  const lower = raw.toLowerCase();
  idx = topics.findIndex(t => t && lower.includes(String(t).toLowerCase().slice(0, 20)));
}
if (idx < 0 || idx >= topics.length) idx = 0;

const topicTitle = topics[idx] || 'Selected topic';
s.topicTitle = topicTitle;
sd['session_' + chatId] = s;

const parts = brief.split(/\bTOPIC\s+\d+\b/i).map(p => p.trim()).filter(Boolean);
const topicBrief = parts[idx] || '';
const hasTitle = /Title:\s*\S/i.test(topicBrief);

// No silent degradation to the full brief. A slice with no Title: field, or one too short to be
// a dossier, means the brief is malformed - fail loudly rather than pass it to the writer.
if (!topicBrief || !hasTitle || topicBrief.length < 80) {
  throw new Error('Topic ' + (idx + 1) + ' has no parsable dossier in the stored brief (' + topicBrief.length + ' chars, Title field ' + (hasTitle ? 'present' : 'missing') + ', ' + parts.length + ' topic slices found). Send /reset and choose the category again.');
}

sd['topicBrief_' + chatId] = topicBrief;

const promptText = 'Topic: ' + topicTitle + '\n\n[RESEARCH]\n' + topicBrief;
return [{ json: { chatId, promptText, topicTitle } }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const sd = $getWorkflowStaticData('global');
const s = sd['session_' + chatId] || {};
s.stage = 'AWAITING_DIRECTION';
sd['session_' + chatId] = s;

const out = $input.first().json.output || '';
const text = '\ud83d\uddc2\ufe0f *Outline \u2014 ' + (s.topicTitle || '') + '*\n\n' + out;
return [{ json: { chatId, text } }];

const chatId = (()=>{try{return $('Telegram Trigger').item.json.message.chat.id}catch(e){return $getWorkflowStaticData('global')['currentChatId']}})();
const sd = $getWorkflowStaticData('global');
const s = sd['session_' + chatId] || {};
const reply = (()=>{try{return $('Detect Stage').item.json.originalText || ''}catch(e){return ''}})();

// Direction used to be free text pasted straight into the prompt. A reply like "explore the
// process and criteria" is a research request wearing a writing instruction's clothes: the
// dossier held nothing on criteria, so the writer invented them. A stance, by contrast, can
// always be satisfied from whatever facts exist, which removes the invitation to invent.
const STANCES = {
  supportive: {
    label: 'Supportive',
    instruction: 'Argue in favour of the subject of this story. Use the dossier to build the strongest honest case for it: what it achieves, who benefits, why it is the right move. Do not invent supporting facts. Where a dossier fact cuts against the case, address it and explain why the case still holds rather than omitting it.'
  },
  critical: {
    label: 'Critical',
    instruction: 'Argue against the subject of this story. Use the dossier to build the strongest honest case that it is inadequate, misdirected, or will not achieve what it claims: what it omits, who it fails, what stays unresolved. Do not invent damaging facts and do not imply wrongdoing the dossier does not report. Criticise the decision, the policy or the claim \u2014 never the personal character of a named individual.'
  },
  neutral: {
    label: 'Neutral',
    instruction: 'Report the story straight. Set out what happened and what each named party\'s position is according to the dossier, and make clear which questions the dossier leaves open. Reach a judgement only where the facts support one.'
  }
};

const t = String(reply).toLowerCase();
let key = 'neutral';
if (/\b(1|one|support|supportive|positive|favourable|favorable|endorse|approve|in favour|in favor)\b/.test(t)) key = 'supportive';
else if (/\b(2|two|critic|critical|criticise|criticize|negative|sceptical|skeptical|against|oppose|opposed|challenge)\b/.test(t)) key = 'critical';
else if (/\b(3|three|neutral|balanced|impartial|objective|straight|report)\b/.test(t)) key = 'neutral';

const stance = STANCES[key];
s.stance = key;
s.direction = stance.label;
sd['session_' + chatId] = s;

const brief = sd['topicBrief_' + chatId] || sd['researchBrief_' + chatId] || '';
const date = sd['researchDate_' + chatId] ||
  new Date().toLocaleDateString('en-GB', {weekday:'long',day:'numeric',month:'long',year:'numeric'});

const promptText = '[CURRENT DATE: ' + date + ']\n\n' +
  'Write the complete article now. Do not ask questions, do not acknowledge, do not send a table of ' +
  'contents. Return the finished article starting with [BLOCK:METADATA].\n\n' +
  'Category: ' + ((s.category && s.category.label) || '') + '\n' +
  'Topic: ' + (s.topicTitle || '') + '\n\n' +
  'STANCE: ' + stance.label + '\n' + stance.instruction + '\n\n' +
  'The stance sets the argument, not the facts. It never licenses a claim the dossier does not ' +
  'support.\n\n' +
  '[LIVE RESEARCH BRIEF - every fact must come from here. Do not invent details:]\n\n' + brief;

return [{ json: { promptText, chatId, stance: key } }];

const sd = $getWorkflowStaticData('global');

// Resolve the query from whichever path we arrived on, without relying on item pairing
// through the Telegram response that sits between Detect Stage and this node.
let q = '';
try { q = $('Detect Stage').first().json.newsQuery || ''; } catch (e) {}
if (!q) { try { q = $('Scheduled Config').first().json.newsQuery || ''; } catch (e) {} }
if (!q) q = sd['currentNewsQuery'] || 'top news';

const chatId = (()=>{try{return $('Telegram Trigger').first().json.message.chat.id}catch(e){return sd['currentChatId']}})();
sd['currentNewsQuery'] = q;

const newsUrl = 'https://news.google.com/rss/search?q=' + encodeURIComponent(q) +
  '&hl=en-GB&gl=GB&ceid=GB:en';

return [{ json: { chatId, newsQuery: q, newsUrl } }];
